#include "portable_pack.h"
#include "audio.h"
#include <iostream>
#include <cmath>
int wmain(int argc,wchar_t**argv){using namespace whic;namespace fs=std::filesystem;if(argc!=3)return 2;Sample s;s.path=argv[1];s.map={60,60,60,1,127,0};std::wstring error;if(!probeSample(s,error))return 3;auto original=recordingSha256(s.path);auto parent=fs::absolute(argv[2]).lexically_normal();auto fixture=parent/(L"portable-test-"+std::to_wstring(GetCurrentProcessId()));fs::create_directory(fixture);auto initial=fixture/L"Portable Test",moved=fixture/L"Moved Pack";auto release=s;release.releaseTrigger=true;DspParameters params;params.blend=.4f;if(!exportPortableInstrument(initial,{s,release},L"Original license / attribution retained",params,error)){std::wcerr<<error;return 4;}if(exportPortableInstrument(initial,{s},L"",params,error))return 5;std::cout<<"PASS existing pack protected from overwrite\n";if(initial.parent_path()!=fixture||moved.parent_path()!=fixture||fixture.parent_path()!=parent)return 6;fs::rename(initial,moved);std::vector<Sample> loaded;std::wstring metadata;DspParameters restored;if(!loadPreset((moved/L"Portable Test.whic").wstring(),loaded,metadata,error,&restored)||loaded.size()!=2||!loaded[1].releaseTrigger||metadata!=L"Original license / attribution retained")return 7;for(auto& z:loaded){if(fs::path(z.path).parent_path()!=moved/L"recordings"||recordingSha256(z.path)!=original)return 8;}unsigned files=0;for(auto&e:fs::directory_iterator(moved/L"recordings"))++files;if(files!=1)return 9;std::cout<<"PASS moved pack resolves relative recordings; SHA256 matches; repeated source deduplicated; release and metadata retained\n";OfflineRender out;if(!AudioEngine::renderOffline(loaded,metadata,false,{{0,60,100},{4000,60,0}},48000,20000,out,error,restored))return 10;double energy=0;for(float f:out.stereo){if(!std::isfinite(f))return 11;energy+=double(f)*f;}if(energy<=0||recordingSha256(s.path)!=original)return 12;std::cout<<"PASS relocated pack finite nonzero offline render; original recording hash unchanged\n";auto missing=s;missing.path=(fixture/L"missing.wav").wstring();if(exportPortableInstrument(fixture/L"Bad",{missing},L"",{},error)||fs::exists(fixture/L"Bad"))return 13;std::cout<<"PASS missing recording fails without publishing a partial pack; no audio streams\n";return 0;}
